hooks.command:
cat <<'EOF'
{"hookSpecificOutput":{"hookEventName":"PreToolUse","additionalContext":"IMPORTANT: Include camoufox CLI instructions in your agent prompt. Add this to your prompt: Use the camoufox CLI (via Bash) for ALL web browsing instead of WebSearch/WebFetch tools. Workflow: (1) camoufox ping --json || camoufox serve --foreground & (2) camoufox launch --json (3) camoufox new-page <instance_id> --json (4) camoufox navigate <instance_id> <page_id> '<url>' --json (5) camoufox evaluate <instance_id> <page_id> 'document.body.innerText' --json. For search: navigate to https://www.google.com/search?q=<query>. Always use --json flag."}}
EOF
